    n1_check("the capture layers are the four that map keys", tuple(mn.NO_REPEAT_LAYERS), ("GAMES_CTRL_MAP", "DVD_BTN_MAP", "REMOTE_REMAP_CAPTURE", "NUMBER_REMAP_CAPTURE"))


