            snap_index = int((datetime.datetime(2026, 10, 29, 10, 0, 5) - start).total_seconds() // 120)
            _sns, truth, (snap, now) = _holiday_truth_run(channel, start, steps, 120, snap_index)
            clock, ticks = [now], [0]
