def suite_dvd_confirm_controller():
    main_src = open(os.path.join(ROOT, "retro_tv_emulator.py"), encoding="utf-8").read()
    deck_src = open(os.path.join(ROOT, "game_deck.py"), encoding="utf-8").read()
